using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DetonationCoilOmenData", menuName = "Data/Battle/Omens System/Omen Data/Hevelius/DetonationCoilOmenData")]
public class DetonationCoilOmenData : OnPlayerCorruptEnemyOmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<HeveliusOmensHandler>.Instance.OnEnemyCorruptionBlockedAction = delegate(GameObject enemyTarget, int corruptionBlockedAmount)
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			OmenLogic.ActivateOmen(null, corruptionBlockedAmount * ActionValue, enemyTarget, null);
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<HeveliusOmensHandler>.Instance.OnEnemyCorruptionBlockedAction = null;
	}

	public override string OmenConvertedDescription()
	{
		string localizedOmenLogicDescription = OmenLogic.GetLocalizedOmenLogicDescription(BattleAction, ActionValue);
		return GetOnCorruptEnemyDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedForEach(), localizedOmenLogicDescription.RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese(), GetOmenRawLocalizedDescription());
	}
}
